/**
 * Small helpers shared by the licence screens. (Tracking references, licence
 * numbers and expiry dates are now generated by lib/company-domain.ts.)
 */

export function isLicenseExpired(expiresAt: string): boolean {
  return new Date(expiresAt).getTime() < Date.now();
}

/** e.g. "TICKET-20261007-AB12CD" — mock support ticket reference. */
export function generateLicenseTicketReference(): string {
  const now = new Date();
  const y = now.getFullYear();
  const m = String(now.getMonth() + 1).padStart(2, "0");
  const d = String(now.getDate()).padStart(2, "0");
  const rand = Math.random().toString(36).slice(2, 8).toUpperCase();
  return `TICKET-${y}${m}${d}-${rand}`;
}
